        {
          "id": "part107_certificate",
          "label": "Remote Pilot Certificate (Part 107)",
          "description": "Remote pilot certificate with small UAS rating. The certificate itself has no expiration date; currency is maintained through recurrent training or testing.",
          "validity": "Does not expire",
          "requiredForCurrency": true
        },
        {
          "id": "part107_initial_knowledge",
          "label": "Initial aeronautical knowledge test",
          "description": "Passing the initial knowledge test establishes currency for the recurrent period.",
          "validity": "24 calendar months (14 CFR 107.65)",
          "requiredForCurrency": false
        },
        {
          "id": "part107_recurrent",
          "label": "Recurrent training (Part 107)",
          "description": "Online recurrent training (or recurrent test) completed within the recency window required to exercise the privileges of the remote pilot certificate.",
          "validity": "24 calendar months (14 CFR 107.65)",
          "requiredForCurrency": true
        },
        {
          "id": "night_operations_training",
          "label": "Night operations training",
          "description": "Training or testing covering night operations, required before conducting operations at night. Satisfied by recurrent training/testing completed after the night-rule effective date.",
          "validity": "Does not expire",
          "requiredForCurrency": false
        },
        {
          "id": "type_specific_training",
          "label": "Type-specific training",
          "description": "Manufacturer or operator training for a specific aircraft type. Expiry set per record.",
          "validity": "Does not expire",
          "requiredForCurrency": false
        },
        {
          "id": "waiver_held",
          "label": "Waiver / certificate of waiver (pilot-held)",
          "description": "A Part 107 waiver issued to the pilot. Expiry is taken from the waiver document.",
          "validity": "Does not expire",
          "requiredForCurrency": false
        }
